-- Precificação: catálogo de serviços da IONEXT com faixa de mercado (pesquisa de nov/2026, com fonte)
-- e o preço que a IONEXT cobra (editável no painel). O orçamento em si é montado no painel; ao usar
-- numa proposta, o valor e a solução vão para oportunidade.proposta_valor / proposta_solucao.

create table if not exists public.servico (
  id           uuid primary key default gen_random_uuid(),
  chave        text unique,                       -- serviços do catálogo inicial; null nos criados no painel
  nome         text not null check (length(nome) between 1 and 120),
  categoria    text not null check (categoria in ('sites', 'sistemas', 'ia_automacao', 'presenca', 'avulso')),
  cobranca     text not null check (cobranca in ('unico', 'mensal', 'anual')),
  unidade      text not null default 'projeto' check (unidade in ('projeto', 'mes', 'ano', 'hora', 'pagina', 'fluxo')),
  descricao    text check (descricao is null or length(descricao) <= 400),
  preco        numeric(12,2) not null check (preco >= 0),           -- preço da IONEXT (editável)
  faixa_min    numeric(12,2) check (faixa_min is null or faixa_min >= 0),
  faixa_max    numeric(12,2) check (faixa_max is null or faixa_max >= 0),
  nota_mercado text check (nota_mercado is null or length(nota_mercado) <= 400),
  fontes       jsonb not null default '[]'::jsonb,                  -- [{titulo, url}]
  ordem        int not null default 100,
  ativo        boolean not null default true,
  criado_em    timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);
alter table public.servico enable row level security;

